// Helper: create vertical gradient texture (0b0b10 → 101017 → 16161d)
function createVerticalGradientTexture(size) {
  const data = new Uint8Array(size * size * 4);
  const c0 = [0x0b, 0x0b, 0x10];
  const c1 = [0x10, 0x10, 0x17];
  const c2 = [0x16, 0x16, 0x1d];

  for (let y = 0; y < size; y++) {
    const t = y / size;
    let r, g, b;

    if (t < 0.7) {
      const s = t / 0.7;
      r = Math.round(c0[0] + (c1[0] - c0[0]) * s);
      g = Math.round(c0[1] + (c1[1] - c0[1]) * s);
      b = Math.round(c0[2] + (c1[2] - c0[2]) * s);
    } else {
      const s = (t - 0.7) / 0.3;
      r = Math.round(c1[0] + (c2[0] - c1[0]) * s);
      g = Math.round(c1[1] + (c2[1] - c1[1]) * s);
      b = Math.round(c1[2] + (c2[2] - c1[2]) * s);
    }

    for (let x = 0; x < size; x++) {
      const idx = (y * size + x) * 4;
      data[idx + 0] = r;
      data[idx + 1] = g;
      data[idx + 2] = b;
      data[idx + 3] = 255;
    }
  }

  const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
  texture.needsUpdate = true;
  return texture;
}

// Helper: create radial gradient texture (center opacity 0.6 → edge opacity 0)
function createRadialGradientTexture(size) {
  const data = new Uint8Array(size * size * 4);
  const center = size / 2;

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx = x - center;
      const dy = y - center;
      const dist = Math.sqrt(dx * dx + dy * dy);
      const t = dist / (center * 0.27);
      const opacity = Math.max(0, 1 - t) * 0.6;

      const idx = (y * size + x) * 4;
      data[idx + 0] = 0;
      data[idx + 1] = 0;
      data[idx + 2] = 0;
      data[idx + 3] = Math.round(opacity * 255);
    }
  }

  const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
  texture.needsUpdate = true;
  return texture;
}
